import javafx.application.Application;
import javafx.stage.Stage;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.layout.BorderPane;
import javafx.scene.control.Label;
import javafx.scene.chart.LineChart;
import javafx.scene.chart.NumberAxis;
import javafx.geometry.Insets;
import javafx.animation.Timeline;
import javafx.animation.KeyFrame;
import javafx.util.Duration;
import javafx.scene.chart.XYChart;
import javafx.scene.chart.XYChart.Series;
import javafx.scene.chart.XYChart.Data;
import java.util.HashMap;
import java.util.Map;

/**
 * A graphical view of the population of each species over time as the
 * simulation runs its courses.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public class StatisticsView extends Application
{
    // Constants representing the JavaFX window properties:
    //   The default size of the window:
    private static final int WINDOW_WIDTH = 800;
    private static final int WINDOW_HEIGHT = 600;
    //   The default title of the window:
    private static final String WINDOW_TITLE = "Statistics";

    // Constants representing JavaFX GUI components:
    //   The root layout component:
    private static BorderPane root;
    //   An informational label explaining the window:
    private static Label infoLabel;
    //   The line chart showing populations:
    private static LineChart<Number, Number> lineChart;
    //   The axes of the population line chart:
    private static NumberAxis xAxis, yAxis;
    //   The XYSeries representing each population over time:
    private static final Map<Class<? extends Actor>, Series<Number, Number>> actorXYSeries = new HashMap<>();

    // The time between updates for the stats:
    private static final double UPDATE_TIME_IN_SECONDS = 0.1;
    // The last day recorded:
    private static int lastDayRecorded = -1; // Set to -1 so we record day 0
    // The highest recorded population:
    private static int highestPopulation = 0;

    /**
     * @param stage The stage (window) for JavaFX.
     */
    @Override
    public void start(Stage stage)
    {
        // Create the root layout component:
        root = new BorderPane();

        // Create the scene:
        Scene scene = new Scene(root, WINDOW_WIDTH, WINDOW_HEIGHT);

        // Create the informational label:
        infoLabel = new Label("The chart below shows the population of each species over time:");

        // Create the line chart:
        lineChart = getPopulationLineChart();
        lineChart.setAnimated(false);

        // Set the initial properties of the root BorderPane:
        final int ROOT_PADDING = 5;
        root.setTop(infoLabel);
        root.setCenter(lineChart);
        root.setPadding(new Insets(ROOT_PADDING, ROOT_PADDING, ROOT_PADDING, ROOT_PADDING));

        // Set the initial properties of the stage and show it:
        stage.setScene(scene);
        stage.setTitle(WINDOW_TITLE);
        stage.show();

        // Create a timeline to update the population line chart at a fixed rate:
        KeyFrame keyFrame = new KeyFrame(Duration.millis(UPDATE_TIME_IN_SECONDS * 1000), e -> updatePopulationLineChart());
        Timeline timeline = new Timeline(keyFrame);
        timeline.setCycleCount(Timeline.INDEFINITE);
        timeline.play();
    }

    /**
     * Create a line chart for the population.
     * 
     * @return A line chart representing population.
     */
    private static LineChart<Number, Number> getPopulationLineChart()
    {
        // Create the axes:
        final int xAxisStep = 5;
        final int yAxisStep = 1000;
        xAxis = new NumberAxis(0, 0, xAxisStep);
        yAxis = new NumberAxis(0, 0, yAxisStep);
        xAxis.setLabel("Days");
        yAxis.setLabel("Population");

        // Create the line chart itself:
        return new LineChart<>(xAxis, yAxis);
    }

    /**
     * Update the data for the population line chart. This is called
     * periodically.
     */
    private void updatePopulationLineChart()
    {
        // Reset if necessary:
        if (Simulator.resetStatisticsView)
        {
            resetPopulationLineChart();
            Simulator.resetStatisticsView = false;
        }

        // Guard statement: Don't continue with this if the day
        // hasn't changed since the last update:
        if (lastDayRecorded == TimeSystem.getCurrentDay()) return;

        // Iterate through each counter in FieldStats:
        Field field = Simulator.getCurrentField();
        Map<Class<? extends Actor>, Counter> counters = Simulator.getFieldStats().getCounters(field);

        for (Map.Entry<Class<? extends Actor>, Counter> entry : counters.entrySet())
        {
            Class<? extends Actor> actorType = entry.getKey();
            Counter counter = entry.getValue();

            // Get the new data to add to the XYSeries:
            Data<Number, Number> newData = new XYChart.Data<>(TimeSystem.getCurrentDay(), counter.getCount());

            // Create a new XYSeries for this actor if there is none already:
            if (!actorXYSeries.containsKey(actorType))
            {
                Series<Number, Number> series = new XYChart.Series<>();
                series.setName(counter.getName());

                lineChart.getData().add(series);

                actorXYSeries.put(actorType, series);
            }

            // Update the XYSeries for this Actor:
            Series<Number, Number> series = actorXYSeries.get(actorType);
            series.getData().add(newData); 

            // Update the highest population if necessary:
            if (counter.getCount() > highestPopulation) highestPopulation = counter.getCount();
        }

        // Set the new last day recorded:
        lastDayRecorded = TimeSystem.getCurrentDay();

        // Set the upper bounds for each of the axes:
        xAxis.setUpperBound(TimeSystem.getCurrentDay());
        yAxis.setUpperBound(highestPopulation);
    }

    /**
     * Reset the population line chart.
     */
    public static void resetPopulationLineChart()
    {
        lineChart = getPopulationLineChart();
        root.setCenter(lineChart);

        lineChart.getData().clear();

        actorXYSeries.clear();

        lastDayRecorded = -1;

        highestPopulation = 0;
    }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A graphical view of the simulation grid. The view displays a colored
 * rectangle for each location representing its contents. It uses a default
 * background color. Colors for each type of species can be defined using the
 * setColor method.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public class SimulatorView extends JFrame
{
    // Colors used for empty locations:
    private static final Color EMPTY_COLOR = Color.white;
    // Color used for objects that have no defined color:
    private static final Color UNKNOWN_COLOR = Color.gray;

    private final String STEP_PREFIX = "Step: ";
    private final String POPULATION_PREFIX = "Population: ";
    private JLabel stepLabel, population, infoLabel, weatherPropertiesLabel,dayLabel;
    private FieldView fieldView;

    // A map for storing colors for participants in the simulation:
    private final Map<Class<? extends Actor>, Color> colors;
    // A statistics object computing and storing simulation information:
    private final FieldStats stats;
    private final Simulator simulator;

    // Threads for each method called by the buttons:
    private Thread runLongSimulationThread;
    private Thread resetThread;
    private Thread simulateOneStepThread;

    /**
     * Create a view of the given width and height.
     *
     * @param height The simulation's height.
     * @param width  The simulation's width.
     */
    public SimulatorView(Simulator simulator, FieldStats stats, int height, int width)
    {
        this.stats = stats;
        colors = new LinkedHashMap<>();
        this.simulator = simulator;
        setTitle("Australian Savannah Simulation");
        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
        infoLabel = new JLabel("  ", JLabel.CENTER);
        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
        dayLabel = new JLabel("Day : 0",JLabel.CENTER);
        JPanel buttonGrid = new JPanel();
        buttonGrid.setLayout(new GridLayout(3,0));
        JButton longSimButton = new JButton("4000 Steps");
        longSimButton.addActionListener(new ActionListener(){
            public void actionPerformed(ActionEvent e){
                if (runLongSimulationThread != null && runLongSimulationThread.isAlive()) return;
                if (simulateOneStepThread != null && simulateOneStepThread.isAlive()) return;

                runLongSimulationThread = new Thread(simulator::runLongSimulation);
                runLongSimulationThread.start();
            }
        });
        JButton resetButton = new JButton("Reset");
        resetButton.addActionListener(new ActionListener(){
            public void actionPerformed(ActionEvent e){
                if (resetThread != null && resetThread.isAlive()) return;
                if (runLongSimulationThread != null && runLongSimulationThread.isAlive()) return;
                if (simulateOneStepThread != null && simulateOneStepThread.isAlive()) return;

                resetThread = new Thread(simulator::reset);
                resetThread.start();
            }
        });
        JButton oneSimButton = new JButton("One Step");
        oneSimButton.addActionListener(new ActionListener(){
            public void actionPerformed(ActionEvent e){
                if (simulateOneStepThread != null && simulateOneStepThread.isAlive()) return;
                if (runLongSimulationThread != null && runLongSimulationThread.isAlive()) return;

                simulateOneStepThread = new Thread(simulator::simulateOneStep);
                simulateOneStepThread.start();
            }
        });

        buttonGrid.add(longSimButton);
        buttonGrid.add(resetButton);
        buttonGrid.add(oneSimButton);
        weatherPropertiesLabel = new JLabel(""); 
        updateWeatherPropertiesLabel();
        updateDayLabel();

        setLocation(100, 50);

        fieldView = new FieldView(height, width);

        Container contents = getContentPane();

        JPanel infoPane = new JPanel(new BorderLayout());
        infoPane.add(stepLabel, BorderLayout.WEST);
        infoPane.add(weatherPropertiesLabel, BorderLayout.EAST);
        infoPane.add(infoLabel, BorderLayout.CENTER);
        infoPane.add(dayLabel);

        contents.add(infoPane, BorderLayout.NORTH);
        contents.add(fieldView, BorderLayout.CENTER);
        contents.add(population, BorderLayout.SOUTH);
        contents.add(buttonGrid,BorderLayout.WEST);
        pack();
        setVisible(true);
    }

    /**
     * Update the text displayed in the weather properties
     * label to reflect the actual weather properties.
     */
    private void updateWeatherPropertiesLabel()
    {
        String text;

        if (WeatherSystem.getIsRaining()) text = "RAINING";
        else                              text = "NOT RAINING";

        weatherPropertiesLabel.setText(text);
    }
    public void updateDayLabel()
    {   
        String text;
        text = "Day : " + TimeSystem.getCurrentDay();
        dayLabel.setText(text);
    }

    /**
     * Define a color to be used for a given class of animal.
     * 
     * @param animalClass The animal's Class object.
     * @param color The color to be used for the given class.
     */
    public void setColor(Class<? extends Actor> animalClass, Color color)
    {
        colors.put(animalClass, color);
    }

    /**
     * Display a short information label at the top of the window.
     */
    public void setInfoText(String text)
    {
        infoLabel.setText(text);
    }

    /**
     * @return The color to be used for a given class of animal.
     */
    private Color getColor(Class<? extends Actor> animalClass)
    {
        Color col = colors.get(animalClass);

        // No color defined for this class:
        if (col == null) return UNKNOWN_COLOR;
        else             return col;
    }

    /**
     * Show the current status of the field.
     * 
     * @param step  Which iteration step it is.
     * @param field The field whose status is to be displayed.
     */
    public void showStatus(int step, Field field)
    {
        if (!isVisible()) setVisible(true);

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for (int row = 0; row < field.getDepth(); row++)
        {
            for (int col = 0; col < field.getWidth(); col++)
            {
                Actor actor = field.getActorAt(row, col);

                if(actor != null)
                {
                    stats.incrementCount(actor.getClass());
                    fieldView.drawMark(col, row, getColor(actor.getClass()));
                }
                else
                {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }

        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));

        updateWeatherPropertiesLabel();
        updateDayLabel();
        fieldView.repaint();
    }

    /**
     * Determine whether the simulation should continue to run.
     * 
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        return stats.isViable(field);
    }

    /**
     * Provide a graphical view of a rectangular field. This is 
     * a nested class (a class defined inside a class) which
     * defines a custom component for the user interface. This
     * component displays the field.
     * This is rather advanced GUI stuff - you can ignore this 
     * for your project if you like.
     */
    private class FieldView extends JPanel
    {
        private final int GRID_VIEW_SCALING_FACTOR = 6;

        private int gridWidth, gridHeight;
        private int xScale, yScale;
        Dimension size;
        private Graphics g;
        private Image fieldImage;

        /**
         * Create a new FieldView component.
         */
        public FieldView(int height, int width)
        {
            gridHeight = height;
            gridWidth = width;
            size = new Dimension(0, 0);
        }

        /**
         * Tell the GUI manager how big we would like to be.
         */
        public Dimension getPreferredSize()
        {
            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
        }

        /**
         * Prepare for a new round of painting. Since the component
         * may be resized, compute the scaling factor again.
         */
        public void preparePaint()
        {
            // If the size has changed:
            if (!size.equals(getSize()))
            {
                size = getSize();
                fieldImage = fieldView.createImage(size.width, size.height);
                g = fieldImage.getGraphics();

                xScale = size.width / gridWidth;

                if (xScale < 1) xScale = GRID_VIEW_SCALING_FACTOR;

                yScale = size.height / gridHeight;

                if (yScale < 1) yScale = GRID_VIEW_SCALING_FACTOR;
            }
        }

        /**
         * Paint on grid location on this field in a given color.
         */
        public void drawMark(int x, int y, Color color)
        {
            g.setColor(color);
            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
        }

        /**
         * The field view component needs to be redisplayed. Copy the
         * internal image to screen.
         */
        public void paintComponent(Graphics g)
        {
            if (fieldImage != null)
            {
                Dimension currentSize = getSize();

                if (size.equals(currentSize)) g.drawImage(fieldImage, 0, 0, null);
                // Else, rescale the previous image:
                else g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
            }
        }
    }
}

